window.FIXTURES=window.FIXTURES||{};window.FIXTURES["speech"]={"vid":"lBQkC6GghCo","speaker":"Geoffrey Hanley","role":"Deputy Prime Minister","country":"Saint Kitts and Nevis","region":"Latin America & Caribbean","url":"https://www.youtube.com/watch?v=lBQkC6GghCo","date":"20260925","title":"🇰🇳 Saint Kitts and Nevis - Deputy Prime Minister Addresses UN General Assembly 81st Session | #UNGA","seconds":1464,"words":2205,"counts":{"claims":33,"promises":0,"attacks":0},"topics":[{"topic":"Climate change","share":0.1378,"seconds":202},{"topic":"AI governance","share":0.0946,"seconds":138},{"topic":"Taiwan relations","share":0.0548,"seconds":80},{"topic":"Youth employment","share":0.052,"seconds":76},{"topic":"Saint Kitts and Nevis development","share":0.0495,"seconds":72},{"topic":"Economic metrics","share":0.0471,"seconds":69},{"topic":"SIDS resilience","share":0.0456,"seconds":67},{"topic":"Haiti politics","share":0.0454,"seconds":66},{"topic":"Caribbean reparations","share":0.0453,"seconds":66},{"topic":"Caribbean-Africa relations","share":0.0444,"seconds":65},{"topic":"UN leadership","share":0.0437,"seconds":64},{"topic":"UN trust","share":0.0436,"seconds":64},{"topic":"Nevis energy","share":0.043,"seconds":63},{"topic":"Digital divide","share":0.0427,"seconds":63},{"topic":"SIDS commitments","share":0.0426,"seconds":62},{"topic":"Water security","share":0.0415,"seconds":61},{"topic":"Financial education","share":0.0415,"seconds":61},{"topic":"International law","share":0.0415,"seconds":61},{"topic":"Ocean governance","share":0.0413,"seconds":60},{"topic":"Ceremony","share":0.0022,"seconds":3}],"timeline":[[1,62,null],[64,126,"SIDS commitments"],[128,200,"Saint Kitts and Nevis development"],[203,263,"Water security"],[266,329,"Nevis energy"],[330,396,"Climate change"],[398,470,"Climate change"],[471,535,"Climate change"],[538,598,"Ocean governance"],[600,666,"SIDS resilience"],[668,737,"Economic metrics"],[738,801,"Digital divide"],[802,868,"AI governance"],[870,943,"AI governance"],[944,1005,"International law"],[1006,1070,"UN leadership"],[1072,1137,"Caribbean-Africa relations"],[1138,1205,"Caribbean reparations"],[1208,1274,"Haiti politics"],[1276,1356,"Taiwan relations"],[1356,1432,"Youth employment"],[1434,1494,"Financial education"],[1496,1560,"UN trust"],[1560,1564,"Ceremony"]],"stances":{"SIDS commitments":"Geoffrey Hanley states that trust will be restored through delivery rather than declarations.","Saint Kitts and Nevis development":"Geoffrey Hanley states that St. Kitts and Nevis is demonstrating tangible progress and delivery on its national blueprint for a resilient and prosperous society by 2040.","Water security":"Geoffrey Hanley states that investments in solar desalination and groundwater exploration have significantly increased household access to water.","Nevis energy":"Geoffrey Hanley outlines specific renewable energy and infrastructure projects in Nevis and St. Kitts aimed at reducing fossil fuel dependence and strengthening resilience.","Climate change":"Geoffrey Hanley states that while St. Kitts and Nevis is advancing partnerships to build a sustainable island state, the intensifying climate crisis presents severe challenges like drought that small island developing states cannot indefinitely adapt to alone.","Ocean governance":"Geoffrey Hanley asserts that ocean contributions must not lead to disproportionate costs for small states and calls for the implementation of the BBNJ agreement alongside fair benefit-sharing and capacity building.","SIDS resilience":"Geoffrey Hanley argues that per capita income is an insufficient metric for measuring the vulnerability of small island developing states to various shocks.","Economic metrics":"Geoffrey Hanley argues that Gross National Income is an inadequate metric for measuring the true vulnerability and resilience of small island states like Saint Kitts and Nevis.","Digital divide":"Geoffrey Hanley argues that vulnerability must be measured and included in financing architecture, warns against a digital divide between nations, and calls for inclusive shaping of the AI age.","AI governance":"Geoffrey Hanley argues that developing nations must have a decisive role in shaping AI's future and require access to affordable infrastructure and safeguards.","International law":"Geoffrey Hanley argues that small states must defend international law as the only lawful path for resolving disputes and preventing power from becoming the rule in conflict zones.","UN leadership":"Geoffrey Hanley endorses Caroline Rodriguez Burket of Guyana for the office of UN Secretary General, citing her understanding of challenges facing developing nations and her identity as an indigenous woman from a small state.","Caribbean-Africa relations":"Geoffrey Hanley argues that Africa-Caribbean cooperation must evolve from sentiment to concrete action through capital, trade, and knowledge transfer, while complementing North-South cooperation.","Caribbean reparations":"Geoffrey Hanley states that while the UN resolution recognizing enslavement as a crime against humanity is historic, recognition alone is insufficient and must be followed by concrete remedies.","Haiti politics":"Geoffrey Hanley calls for the full deployment of a UN-authorized gang suppression force and emphasizes that Haitian people must choose their leaders freely, credibly, and safely.","Taiwan relations":"Geoffrey Hanley states that Saint Kitts and Nevis remains steadfast in its friendship with Taiwan and supports its meaningful international participation.","Youth employment":"Geoffrey Hanley states that young people have a significant stake in decisions and highlights the need to prepare them for future job challenges through specific government programs.","Financial education":"Geoffrey Hanley states that Saint Kitts and Nevis is piloting a financial education curriculum in schools to ensure financial independence is accessible to all, not just the wealthy.","UN trust":"Geoffrey Hanley argues that trust must be earned through action rather than demands and calls for the assembly to focus on results.","Ceremony":"The speaker expresses gratitude to the deputy prime minister of St. Kitts and Nevis."},"claims":[{"t":83,"quote":"I rise before this assembly at a time when the world is not short of declarations or commitments.","topic":"SIDS commitments","kind":"fact"},{"t":182,"quote":"Earlier this year, our second voluntary national review in the United Nations high level political forum showed stronger government coordination, closer alignment with sustainable development goals and tangible progress for our people.","topic":"Saint Kitts and Nevis development","kind":"fact"},{"t":209,"quote":"One year ago, our 2 milliongal per day solar power dissalination plant was nearing completion. In February, we commissioned it.","topic":"Water security","kind":"fact"},{"t":248,"quote":"In 2022, only 25% of our households had 247 water. Today, approximately 75% do.","topic":"Water security","kind":"number"},{"t":266,"quote":"On the island of NEAS, we advancing a 30 megawatt geothermal power development with drilling expected by early 2027 and Icelandic drillers contracted to begin the process.","topic":"Nevis energy","kind":"number"},{"t":286,"quote":"In St. kits. Plans for a 50 megawatt solar PV and battery storage project are well advanced.","topic":"Nevis energy","kind":"number"},{"t":377,"quote":"By the end of May, rainfall was 44% below the long-term average.","topic":"Climate change","kind":"number"},{"t":410,"quote":"The years 2015 to 2025 were the warmest on record.","topic":"Climate change","kind":"fact"},{"t":416,"quote":"And in 2025, global average temperature remained about 1.43° C above the pre-industrial baseline, while global mean sea level stood approximately 11 cm higher than in 1993.","topic":"Climate change","kind":"number"},{"t":471,"quote":"The International Law Commission has laid foundations for continuity of statehood, sovereignty, maritime This assembly must turn them into firm International law has spoken with the increasing clarity.","topic":"Climate change","kind":"fact"},{"t":494,"quote":"St. Kitsanis welcomed the international court of justice advisory opinion on states climate obligations.","topic":"Climate change","kind":"fact"},{"t":553,"quote":"St. Kitsanis ratified the BBJ agreement in 2025.","topic":"Ocean governance","kind":"fact"},{"t":605,"quote":"For decades, small island developing states have argued that income is not the same as resilience.","topic":"SIDS resilience","kind":"fact"},{"t":639,"quote":"This year, St. Kets stood before the United Nations and completed the pilot vulnerability and resilient country profile under the multi-dimensional vulnerability index framework.","topic":"SIDS resilience","kind":"fact"},{"t":679,"quote":"It is a family rebuilding for the third time in a decade because storms have no patience for GNI per capita.","topic":"Economic metrics","kind":"fact"},{"t":729,"quote":"nations twice our size and half of of our vulnerability borrowed cheaper than we do","topic":"Economic metrics","kind":"fact"},{"t":795,"quote":"At the end of 2025, some 2.2 billion people remain offline.","topic":"Digital divide","kind":"number"},{"t":815,"quote":"global the global AI market projected to reach US $4.8 8 trillion by 2033","topic":"AI governance","kind":"number"},{"t":872,"quote":"at home we are advancing a whole of government technological strategy securing digital identity and digital public services.","topic":"AI governance","kind":"fact"},{"t":883,"quote":"Regionally, the Caribbean AI Task Force supports cooperation and governance, innovation, and responsible adoption.","topic":"AI governance","kind":"fact"},{"t":944,"quote":"Cariccom supports the international court of justice as the lawful path for resolving the Guyana Venezuela dispute and the judicial process concerning Bise and Guatemala.","topic":"International law","kind":"fact"},{"t":966,"quote":"alternatives is a world where power becomes the rule across Gaza, Ukraine, Sudan, Yemen, Chad and the Democratic Republic of the Congo.","topic":"International law","kind":"fact"},{"t":1014,"quote":"St. Kit Sanas proudly joins Caraccom in endorsing her excellency Caroline Rodriguez Burket of Guyana for the office of the United Nations Secretary General.","topic":"UN leadership","kind":"fact"},{"t":1029,"quote":"Her understanding of the challenges facing developing nations reflect the leadership this moment demands.","topic":"UN leadership","kind":"fact"},{"t":1130,"quote":"At the second African Caribbean submit, our leaders signed the Abi Adisa Baba Declaration.","topic":"Caribbean-Africa relations","kind":"fact"},{"t":1140,"quote":"the African Union's reparation mechanism and the Caribbean Reparations Commission held their first joint meeting establishing permanent on March 25th, 2026","topic":"Caribbean reparations","kind":"fact"},{"t":1159,"quote":"This general assembly adopted resolution 80 25 250 declaring that trafficking of enslaved African and racialized chatel enslavement of Africans as the gravest crime against humanity","topic":"Caribbean reparations","kind":"fact"},{"t":1209,"quote":"47 million people are eternally displaced while nearly half of the population faces acute food insecurity.","topic":"Haiti politics","kind":"number"},{"t":1324,"quote":"Earlier this year, we join our member states in requesting Taiwan's obser observer participation in the 79th World Health Assembly.","topic":"Taiwan relations","kind":"fact"},{"t":1364,"quote":"Half of the world's population is under 30. Yet 67 million young people were unemployed last year and more than a quarter of a billion were neither in employment, education nor training.","topic":"Youth employment","kind":"number"},{"t":1418,"quote":"Aspire has opened more than 4,000 savings accounts with our government committing more than US 2 million to give children a financial foundation for adulthood.","topic":"Youth employment","kind":"number"},{"t":1434,"quote":"We are now piloting our financial education curriculum in schools and training teachers for national roll out.","topic":"Financial education","kind":"fact"},{"t":1501,"quote":"St. Kitsanius remains ready to do its part and to work with every nation here towards a more peaceful, sustainable, equitable and humane world.","topic":"UN trust","kind":"fact"}],"promises":[],"attacks":[],"greece":[],"said":[],"pickup":[],"transcript":[{"t":1,"topic":null,"text":"And now I give the floor to his excellency Jeffrey Hunley, Deputy Prime Minister of St. Kits and Navies. Mr. President, Secretary General, distinguished delegates, friends, and my fellow kitians and divisions at home and throughout the I bring greetings from the proud twin island of St. Kits and Nevis and our prime minister the honorable Dr. Terren Drew."},{"t":64,"topic":"SIDS commitments","text":"Mr. President, we extend congratulations on your elections as president of the 81st session of this assembly. We also express sincere appreciation to your predecessor for her stewardship over the past year. I rise before this assembly at a time when the world is not short of declarations or commitments. What we need is proof that our can respond to the realities people For small island developing states like ours, the question is immediate. St. Kit San therefore comes with a clear Trust will be restored not by what we but by what we deliver."},{"t":128,"topic":"Saint Kitts and Nevis development","text":"The time has come to move from promise to proof. I come not only to speak about what the world must do but to account for what we are doing. Mr. President, last year our prime minister, the honorable Dr. Terren Drew spoke of our sustainable island state agenda CISA our national blueprint for transforming St. into a more resilient sustainable inclusive and [clears throat] prosperous society by 2040. Today we return to demonstrate that it is becoming a record of delivery. Earlier this year, our second voluntary national review in the United Nations high level political forum showed stronger government coordination, closer alignment with sustainable development goals and tangible progress for our people."},{"t":203,"topic":"Water security","text":"Water provides one of the clearest measures of that progress. One year ago, our 2 milliongal per day solar power dissalination plant was nearing completion. In February, we commissioned it. through semi-airborne drone surveys. We are also identified 17 new potential groundwater sources and in August completed drilling at the first rural site together with distribution of grades. These investments are strengthening water security. In 2022, only 25% of our households had 247 water. Today, approximately 75% do. This is transformation."},{"t":266,"topic":"Nevis energy","text":"On the island of NEAS, we advancing a 30 megawatt geothermal power development with drilling expected by early 2027 and Icelandic drillers contracted to begin the process. In St. kits. Plans for a 50 megawatt solar PV and battery storage project are well advanced. These investments will reduce dependence on imported fossil fuels and strengthen economic resilience. We are also strengthening food security through climate smart support for farmers and health care through our locally developed national digital health information system at the Joseph and France General Hospital. must be practical, people centered and built to last."},{"t":330,"topic":"Climate change","text":"Mr. President, there is more to do. But our experience proves that small states are not powerless. With investment, partnership and political will, small nations can deliver big solutions. St. Kits and Nevice is not seeking pity. We are advancing partnership. A sustainable island state is not a distant ambition. We are building it Yet even as we advance, the climate crisis is moving the goalpost. This year, our federation and the wider Caribbean face severe drought. By the end of May, rainfall was 44% below the long-term average. We are investing in resilient infrastructure. But no small island developing state can adapt indefinitely to a crisis the world continues to intensify."},{"t":398,"topic":"Climate change","text":"Adaptation cannot excuse in action Distinguished colleagues, the science is The years 2015 to 2025 were the warmest on record. And in 2025, global average temperature remained about 1.43° C above the pre-industrial baseline, while global mean sea level stood approximately 11 cm higher than in 1993. For island nations, this is a question of sovereignty and statethood. If our coastlines retreat, our sovereignty must not. Mr. President, climate induced sea level rise must never erase a state's international legal personality, extinguish its UN membership, deprive its people of nationality, or diminish lawfully established maritime zones of sovereign rights."},{"t":471,"topic":"Climate change","text":"The International Law Commission has laid foundations for continuity of statehood, sovereignty, maritime This assembly must turn them into firm International law has spoken with the increasing clarity. St. Kitsanis welcomed the international court of justice advisory opinion on states climate obligations. Clarification must now become Compliments must become conduct and promises must become performance. States must reduce emissions, strengthen adaptation, honor climate finance responsibilities, and cooperate with countries bearing consequences vastly disos to their contribution to this crisis."},{"t":538,"topic":"Ocean governance","text":"Mr. President, those contributions least must not pay the greatest price. Our oceans must also move from promises to protection. St. Kitsanis ratified the BBJ agreement in 2025. Implementation now matters. Large ocean states needs access to capacity building marine technology, scientific knowledge and financing. While benefits for marine genetics resources must be shared fairly for us island nations, the ocean is not the space between us and the world. It is our highway, livelihood and lifeline. Across climate action, sea level rise and ocean governance."},{"t":600,"topic":"SIDS resilience","text":"One reality remains. Resilience has a cost. For decades, small island developing states have argued that income is not the same as resilience. Mr. President per capita income cannot show exposure to hurricanes, droughts, pandemic, ship shipping disruptions, energy shocks, conflict or tourist Nor how quickly one shock can erase years of investment. This year, St. Kets stood before the United Nations and completed the pilot vulnerability and resilient country profile under the multi-dimensional vulnerability index framework. And what did we learn? We learned what our grandparents always knew. A house can look strong from the road and still have rot in the rafters."},{"t":668,"topic":"Economic metrics","text":"Vulnerability is not a statistic. It is a roof that was destroyed in hurricane burial. It is a school that became a shelter. It is a family rebuilding for the third time in a decade because storms have no patience for GNI per capita. Mr. President, we are not asking that gross national income be discarded. We are asking that it stop being expected to tell a story it was never designed to tell. GNI can count our coconuts and our cruise ships. It cannot count our courage and it cannot count the price we pay to simply remain. It cannot capture the cost of rebuilding the same bridge, clinic or seaw wall again and again while nations twice our size and half of of our vulnerability borrowed cheaper than we do."},{"t":738,"topic":"Digital divide","text":"We therefore call on the World Bank, the IMF, development banks, climate funds, and every partner here to incorporate NVI into the architecture of financing, not as charity, but as arithmetic and justice made real. If vulnerability can be measured, it must be considered. Mr. President, the next great divide between nations must not be digital. Artificial intelligence offers extraordinary possibilities. St. Kit Sanas intends to participate, but we must ask who will shape this new age and who will live with decisions made At the end of 2025, some 2.2 billion people remain offline."},{"t":802,"topic":"AI governance","text":"But the AI divide also concern computing, power, data, research, skills, energy, cyber security, and capital with the global the global AI market projected to reach US $4.8 8 trillion by 2033. Developing countries cannot simply consume technologies designed and governed elsewhere. We must have a place where AI's future is decided. St. Kits welcomes the independent international scientific panel on artificial intelligence and the global dialogue on AI governance. Inclusion must lead to capability. Developing countries need affordable computing power, infrastructure, skills and safeguard for privacy, data sovereignty, cyber security and rights."},{"t":870,"topic":"AI governance","text":"Mr. President, at home we are advancing a whole of government technological strategy securing digital identity and digital public services. Regionally, the Caribbean AI Task Force supports cooperation and governance, innovation, and responsible adoption. Mr. President, artificial intelligence is already transforming the world. St. chooses to help shape that As Sids, we know a simple truth. Alone we are small. Together we are formidable. The Caribbean Declaration as a zone of peace must retain its force as geopolitical competition moves closer to our shores. Our response must remain anchored in sovereignty, territorial integrity, international law, peaceful settlement of disputes and diplomacy."},{"t":944,"topic":"International law","text":"Cariccom supports the international court of justice as the lawful path for resolving the Guyana Venezuela dispute and the judicial process concerning Bise and Guatemala. We defend international law because for small states especially the alternatives is a world where power becomes the rule across Gaza, Ukraine, Sudan, Yemen, Chad and the Democratic Republic of the Congo. Civilians continue to bear an unconscionable burden. St. Kitanis affirms one standard international law applied consistently not selectively and conscience applied evenly not conveniently. There can be no hierarchy of human suffering."},{"t":1006,"topic":"UN leadership","text":"Mr. President the future of also depends on its leadership. St. Kit Sanas proudly joins Caraccom in endorsing her excellency Caroline Rodriguez Burket of Guyana for the office of the United Nations Secretary General. Her understanding of the challenges facing developing nations reflect the leadership this moment demands. Her candidature as an indigenous woman from a small developing state also reaffirms that global leadership must be defined not by the size of a nation but by the vision, integrity and capacity of those called to serve. Mr. President, few bridges carry greater historical meaning or future potential than between Africa and the Caribbean."},{"t":1072,"topic":"Caribbean-Africa relations","text":"The Atlantic, once a passage of forced displacement and separation, is becoming a pathway of return and reconnection. Africa Caribbean cooperation must move beyond sentiment. Our shared history must help build a shared future through capital, trade, knowledge, culture and coordinated Mr. President South South cooperation must be felt in jobs, businesses, knowledge transfer and opportunity. It complements, not replaces, north south cooperation and the obligations of developed country. Greater accuracy must also include justice. At the second African Caribbean submit, our leaders signed the Abi Adisa Baba Declaration."},{"t":1138,"topic":"Caribbean reparations","text":"And this year, the African Union's reparation mechanism and the Caribbean Reparations Commission held their first joint meeting establishing permanent on March 25th, 2026. This general assembly adopted resolution 80 25 250 declaring that trafficking of enslaved African and racialized chatel enslavement of Africans as the gravest crime against humanity. St. Kitanius welcomed this historic recognition. But recognition cannot be the destination. Repatory justice must move from recognition to remedy and from words to Distinguished colleagues, when we speak of repatory justice, sovereignty and Haiti cannot be an afterthought."},{"t":1208,"topic":"Haiti politics","text":"1.47 47 million people are eternally displaced while nearly half of the population faces acute food insecurity. In the very near future, the first round of presidential and legislative elections will take place. The Haitian people must choose their leaders freely, credibly, and safely. Mr. President St. Kit San joins CARICOM in calling for the full deployment of the United Nations authorized gang suppression force and the timely renewal of its mandate alongside Haitianled recovery and governance. Mr. President, we remain deeply concerned about the humanitarian situation in Cuba. St. Kissan has contributed to humanitarian relief to the Cuman people and our own nationals studying there."},{"t":1276,"topic":"Taiwan relations","text":"We welcome the recent measures undertaken by the Cuban government to improve the well-being of its people and encourage further meaningful action. We urge constructive dialogue between the governments of Cuba and the United States. mutual respect and cooperation offers a best path, improving the lives of the Cuban people and advancing peace and stability throughout our region. Mr. President, St. Kitsanis remains steadfast in its friendship with the Republic of China, Taiwan, and supports for its meaningful international Earlier this year, we join our member states in requesting Taiwan's obser observer participation in the 79th World Health Assembly. We continue to support its meaningful participation in the World Health Organization, the International Civil Aviation and other relevant mechanisms, and reiterate that differences across the Taiwan Strait must be resolved Mr."},{"t":1356,"topic":"Youth employment","text":"President, no generation has a greater stake in our decisions than young people. Half of the world's population is under 30. Yet 67 million young people were unemployed last year and more than a quarter of a billion were neither in employment, education nor training. AI, the green transition and climate change are reshaping their future jobs. We must prepare them. Last year, our prime minister introduced this assembly to our Aspire program. Achieving success through personal investment, resources, and education for citizens aged 5 to 18. Built on savings, investment, and financial education, Aspire has opened more than 4,000 savings accounts with our government committing more than US 2 million to give children a financial foundation for adulthood."},{"t":1434,"topic":"Financial education","text":"We are now piloting our financial education curriculum in schools and training teachers for national roll out. We are not simply giving children money. We are giving them the knowledge to make money work for them. Financial independence must not be reserved for those born into wealth. Finally, Mr. President, distinguished colleagues, for 81 years, this institution has represented a bold that despite our differences, nations can come together across common rules, responsibilities, and human dignity. That conviction is worth defending. But institutions cannot live indefinitely on those founding promises."},{"t":1496,"topic":"UN trust","text":"They must be judged by what those promises produce. St. Kitsanius remains ready to do its part and to work with every nation here towards a more peaceful, sustainable, equitable and humane world. Mr. President, trust is not something we can demand. It must be earned by promising less, delivering more, and letting the proof speak where our words once stood alone. Let this assembly be remembered not for what was said here but for what was done The tide is rising. Let our resolve rise faster still. Thank Thank you."},{"t":1560,"topic":"Ceremony","text":"I thank the deputy prime minister of St. Kits and Navies."}],"compare":[{"topic":"Climate Change","share":0.1381,"mean":0.0423,"rank":20,"others":77},{"topic":"Artificial Intelligence","share":0.0948,"mean":0.0502,"rank":39,"others":83},{"topic":"UN & its reform","share":0.0875,"mean":0.2054,"rank":150,"others":170},{"topic":"Latin America","share":0.0872,"mean":0.0042,"rank":4,"others":12},{"topic":"Taiwan","share":0.0549,"mean":0.0026,"rank":4,"others":7},{"topic":"Youth","share":0.0521,"mean":0.0022,"rank":4,"others":5},{"topic":"Global Economy","share":0.0472,"mean":0.0144,"rank":31,"others":31},{"topic":"Small states","share":0.0457,"mean":0.0022,"rank":7,"others":6}]};
